/**
 * 聊天相关API服务
 * 提供会话管理、消息发送等功能
 */
import { ApiClient } from './client-api';
import { ApiResponse } from './definitions';
import {
    API_SESSION_LIST,
    API_SESSION_CREATE,
    API_SESSION_UPDATE,
    API_SESSION_DELETE,
    API_MESSAGE_SEND,
    API_MESSAGE_LIST,
    API_MESSAGE_STREAM
} from './api-url';
import {
    SessionResponseInfo,
    ChatHistoryResponseInfo,
    MessageSendResponseInfo,
    MessageListResponseInfo,
    SessionUpdateParams,
    MessageSendParams,
    StreamMessageCallback,
    StreamErrorCallback,
    StreamEndCallback,
    StreamController,
    StreamMessageData,
    StreamEndData
} from '../models/chat-models';
import { GenericResponseData } from '../models/base-models';
import { getAccessToken } from '../utils/auth';

/**
 * 聊天API服务类
 * 集中管理所有聊天相关的API调用
 */
export class ApiChat {
    /**
     * 创建会话
     * @param title 会话标题
     * @param model 使用的AI模型
     * @returns 创建的会话信息
     */
    static async createSession(title: string, model: string | null): Promise<ApiResponse<SessionResponseInfo>> {
        const requestData: any = { title };
        if (model) {
            requestData.model = model;
        }

        return await ApiClient.post(
            API_SESSION_CREATE,
            requestData,
            SessionResponseInfo
        );
    }

    /**
     * 获取会话历史（分页）
     * @param page_size 每页数量，默认为10，最大50
     * @param cursor 游标ID，用于分页（传入上一页最后一条记录的ID）
     * @returns 会话历史列表
     */
    static async getChatHistory(page_size: number = 10, cursor: number | string | null = null): Promise<ApiResponse<ChatHistoryResponseInfo>> {
        return await ApiClient.post(
            API_SESSION_LIST,
            { page_size, cursor },
            ChatHistoryResponseInfo
        );
    }

    /**
     * 更新会话信息
     * @param params 会话更新参数
     * @returns 更新结果
     */
    static async updateSession(params: SessionUpdateParams): Promise<ApiResponse<SessionResponseInfo>> {
        return await ApiClient.post(
            API_SESSION_UPDATE,
            params,
            SessionResponseInfo
        );
    }

    /**
     * 删除会话
     * @param id 会话ID
     * @returns 删除结果
     */
    static async deleteSession(id: number): Promise<ApiResponse<SessionResponseInfo>> {
        return await ApiClient.post(
            API_SESSION_DELETE,
            { id },
            SessionResponseInfo
        );
    }

    /**
     * 发送聊天消息
     * @param params 消息发送参数
     * @returns 发送结果，包含AI回复消息
     */
    static async sendChatMessage(params: MessageSendParams): Promise<ApiResponse<MessageSendResponseInfo>> {
        return await ApiClient.post(
            API_MESSAGE_SEND,
            params,
            MessageSendResponseInfo
        );
    }

    /**
     * 获取会话消息列表
     * @param session_id 会话ID
     * @param page_size 每页数量，默认为20，最大50
     * @param cursor 游标ID，用于分页（传入上一页最后一条记录的ID）
     * @returns 消息列表
     */
    static async getChatMessageList(session_id: number, page_size: number = 20, cursor: number | null = null): Promise<ApiResponse<MessageListResponseInfo>> {
        return await ApiClient.post(
            API_MESSAGE_LIST,
            { session_id, page_size, cursor },
            MessageListResponseInfo
        );
    }

    /**
     * 发送流式聊天消息
     * @param params 消息发送参数
     * @param onMessage 接收流式消息的回调函数
     * @param onError 错误处理回调函数
     * @param onEnd 流结束时的回调函数
     * @returns 返回一个包含close方法的控制器，用于取消请求
     */
    static sendStreamChatMessage(
        params: MessageSendParams,
        onMessage: StreamMessageCallback,
        onError?: StreamErrorCallback,
        onEnd?: StreamEndCallback
    ): StreamController {
        // 构建URL和请求参数
        const baseURL = process.env.VITE_BASE_URL + process.env.VITE_API_URL;
        const token = getAccessToken();
        const url = `${baseURL}${API_MESSAGE_STREAM}`;

        // 创建AbortController用于取消请求
        const controller = new AbortController();
        const { signal } = controller;

        // 发起fetch请求
        fetch(url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`,
            },
            body: JSON.stringify(params),
            signal,
        })
        .then(response => {
            if (!response.ok) {
                throw new Error(`HTTP error! Status: ${response.status}`);
            }

            // 获取响应的reader
            const reader = response.body?.getReader();
            if (!reader) {
                throw new Error('Failed to get response reader');
            }

            const decoder = new TextDecoder('utf-8');
            let buffer = ''; // 用于存储不完整的消息片段
            let accumulatedText = ''; // 用于累积所有文本

            // 处理数据流
            const processStream = async (): Promise<void> => {
                try {
                    while (true) {
                        const { done, value } = await reader.read();

                        if (done) {
                            // 处理缓冲区中可能剩余的数据
                            if (buffer.trim()) {
                                processBufferContent(buffer);
                            }

                            // 流结束时，检查整个累积文本中是否包含citations数据
                            if (accumulatedText.includes('citations') || accumulatedText.includes('{"type"')) {
                                // 尝试从整个累积文本中提取citations - 支持多种格式
                                const extractCitations = (text: string): string[] | null => {
                                    try {
                                        // 格式1: {"type": "citations", "data": [...]}
                                        const typeMatch = text.match(/\{"type":\s*"citations"[^}]*"data":\s*(\[[^\]]*\])\}/);
                                        if (typeMatch) {
                                            const citationsData = JSON.parse(`{"type": "citations", "data": ${typeMatch[1]}}`);
                                            if (Array.isArray(citationsData.data)) {
                                                return citationsData.data;
                                            }
                                        }

                                        // 格式2: 直接的数组格式 ["url1", "url2", ...]
                                        const arrayMatch = text.match(/\[(?:\s*"[^"]*"\s*,?\s*)+\]/);
                                        if (arrayMatch) {
                                            const arrayData = JSON.parse(arrayMatch[0]);
                                            if (Array.isArray(arrayData) && arrayData.every(item => typeof item === 'string' && item.startsWith('http'))) {
                                                return arrayData;
                                            }
                                        }

                                        // 格式3: 包含citations字段的JSON对象
                                        const jsonMatches = text.match(/\{[^{}]*"citations"[^{}]*\}/g);
                                        if (jsonMatches) {
                                            for (const match of jsonMatches) {
                                                try {
                                                    const jsonObj = JSON.parse(match);
                                                    const citations = jsonObj.citations || jsonObj.search_citations || jsonObj.references;
                                                    if (Array.isArray(citations) && citations.length > 0) {
                                                        return citations;
                                                    }
                                                } catch (e) {
                                                    continue;
                                                }
                                            }
                                        }

                                        return null;
                                    } catch (error) {
                                        return null;
                                    }
                                };

                                const extractedCitations = extractCitations(accumulatedText);
                                if (extractedCitations && extractedCitations.length > 0) {
                                    // 发送citations数据
                                    if (onMessage) {
                                        onMessage({
                                            content: '',
                                            full_content: accumulatedText,
                                            is_text: false,
                                            citations: extractedCitations
                                        });
                                    }
                                }
                            }

                            // 流结束
                            if (onEnd) onEnd({ content: accumulatedText });
                            break;
                        }

                        // 解码二进制数据
                        const chunk = decoder.decode(value, { stream: true });
                        
                        buffer += chunk;

                        // 处理完整的消息
                        // 使用正则表达式匹配SSE消息格式
                        // 支持多种格式: "data: ...\n\n", "data:...\n\n", "data: ...\r\n\r\n"
                        const regex = /data:[ ]?(.*?)(?:\n|\r\n)/g;
                        let match;
                        let lastIndex = 0;

                        // 查找所有完整的消息
                        while ((match = regex.exec(buffer)) !== null) {
                            const content = match[1];
                            processContent(content);
                            lastIndex = regex.lastIndex;
                        }

                        // 保留未处理的部分到缓冲区
                        if (lastIndex > 0) {
                            buffer = buffer.substring(lastIndex);
                        }

                        // 如果缓冲区过大但没有找到完整消息，尝试更宽松的处理
                        const MAX_BUFFER_SIZE = 100000; // 100KB
                        if (buffer.length > MAX_BUFFER_SIZE) {
                            // 尝试查找任何可能的data标记
                            const dataIndex = buffer.lastIndexOf('data:');
                            if (dataIndex >= 0) {
                                // 提取最后一个data标记后的内容
                                const partialContent = buffer.substring(dataIndex + 5).trim();
                                if (partialContent) {
                                    processContent(partialContent);
                                }
                            }

                            // 保留最后一部分可能的消息开头
                            buffer = buffer.substring(buffer.length - 1000);
                        }
                    }
                } catch (error) {
                    if (error instanceof Error && error.name === 'AbortError') {
                        // 请求被取消，不需要处理
                    } else {
                        if (onError) onError(error as Error);
                    }
                }
            };

            // 处理单条消息内容
            const processContent = (content: string): void => {
                try {
                    // 检查是否是 citations 数据 - 支持多种格式
                    const trimmedContent = content.trim();
                    
                    // 格式1: {"type": "citations", "data": [...]}
                    if (trimmedContent.startsWith('{"type": "citations"') || 
                        trimmedContent.startsWith('{"type":"citations"')) {
                        try {
                            const citationsData = JSON.parse(trimmedContent);
                            if (citationsData.type === 'citations' && Array.isArray(citationsData.data)) {
                                if (onMessage) {
                                    onMessage({
                                        content: '',
                                        full_content: accumulatedText,
                                        is_text: false,
                                        citations: citationsData.data
                                    });
                                }
                                return;
                            }
                        } catch (e) {
                            // 解析失败，按普通文本处理
                        }
                    }
                    
                    // 格式2: 直接的数组格式 ["url1", "url2", ...]
                    if (trimmedContent.startsWith('[') && trimmedContent.endsWith(']')) {
                        try {
                            const arrayData = JSON.parse(trimmedContent);
                            if (Array.isArray(arrayData) && arrayData.length > 0 && 
                                arrayData.every(item => typeof item === 'string' && item.startsWith('http'))) {
                                if (onMessage) {
                                    onMessage({
                                        content: '',
                                        full_content: accumulatedText,
                                        is_text: false,
                                        citations: arrayData
                                    });
                                }
                                return;
                            }
                        } catch (e) {
                            // 不是有效的JSON数组，继续处理为普通文本
                        }
                    }
                    
                    // 格式3: 检查是否包含 citations 关键字的JSON
                    if (trimmedContent.includes('citations') && 
                        (trimmedContent.startsWith('{') || trimmedContent.startsWith('['))) {
                        try {
                            const jsonData = JSON.parse(trimmedContent);
                            // 检查各种可能的citations字段
                            const citationsArray = jsonData.citations || jsonData.search_citations || 
                                                  jsonData.references || jsonData.sources;
                            if (Array.isArray(citationsArray) && citationsArray.length > 0) {
                                if (onMessage) {
                                    onMessage({
                                        content: '',
                                        full_content: accumulatedText,
                                        is_text: false,
                                        citations: citationsArray
                                    });
                                }
                                return;
                            }
                        } catch (e) {
                            // 解析失败，按普通文本处理
                        }
                    }

                    // 处理普通文本内容
                    let textContent = content;

                    // 移除可能的引号（如果服务器发送的是带引号的字符串）
                    if (content.startsWith('"') && content.endsWith('"')) {
                        try {
                            textContent = JSON.parse(content); // 解析JSON字符串
                        } catch (e) {
                            // 如果解析失败，可能是引号内有未转义的引号，尝试手动处理
                            if (content.length > 2) {
                                textContent = content.substring(1, content.length - 1);
                            }
                        }
                    }

                    // 处理转义字符：将文本中的 \\n 转换为实际的换行符
                    textContent = textContent.replace(/\\n/g, '\n');
                    textContent = textContent.replace(/\\r/g, '\r');

                    // 累积文本
                    accumulatedText += textContent;

                    // 发送消息，保留原始格式
                    if (onMessage) {
                        onMessage({
                            content: textContent,
                            full_content: accumulatedText,
                            is_text: true
                        });
                    }
                } catch (error) {
                    // 即使解析失败，也尝试将原始内容发送给回调
                    if (onMessage) {
                        onMessage({
                            content: content,
                            parse_error: true
                        });
                    }
                }
            };

            // 处理缓冲区内容
            const processBufferContent = (buffer: string): void => {
                if (buffer.startsWith('data: ')) {
                    const content = buffer.substring(6).trim();
                    processContent(content);
                } else if (buffer.startsWith('data:')) {
                    const content = buffer.substring(5).trim();
                    processContent(content);
                } else if (buffer.trim()) {
                    // 如果不是标准格式但有内容，尝试处理
                    processContent(buffer.trim());
                }
            };

            // 开始处理流
            processStream();
        })
        .catch(error => {
            if (onError) onError(error);
        });

        // 返回一个对象，包含取消请求的方法
        return {
            close: (): void => {
                controller.abort();
            }
        };
    }
}